/bin/zsh -lc "python3 - <<'PY'
import json, pathlib
for name in ['policy.json','coordination.json','source.json']:
 p=pathlib.Path(name); d=json.loads(p.read_text()); print(name, 'bytes',p.stat().st_size, 'type',type(d).__name__)
 if name"'!='"'source.json': print(json.dumps(d,ensure_ascii=False,indent=2))
 else:
  print('keys',list(d) if isinstance(d,dict) else '')
  items=d if isinstance(d,list) else d.get('articles',d.get('sources',[]))
  for i,a in enumerate(items): print(i, {k:v for k,v in a.items() if k not in ['source_xml','source_notes_xml']}, 'xml length',len(a.get('source_xml','')), 'notes length',len(a.get('source_notes_xml') or ''))
PY"

